-- Matches the inspected Django model; used only on a disposable EchoLink branch.
CREATE SCHEMA website_probe;
CREATE TABLE website_probe.nobleseek_article (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  headline varchar(255) NOT NULL,headline_bn varchar(255) NOT NULL,
  slug varchar(200) NOT NULL UNIQUE,excerpt varchar(300) NOT NULL,
  body_html text NOT NULL,hero_image varchar(500) NOT NULL,
  hero_image_alt varchar(255) NOT NULL,image_credit varchar(255) NOT NULL,
  source_name varchar(255) NOT NULL,source_url varchar(500) NOT NULL,
  tags jsonb NOT NULL,status varchar(10) NOT NULL,
  is_featured boolean NOT NULL,is_breaking boolean NOT NULL,
  related_product_ids jsonb NOT NULL,seo_title varchar(255) NOT NULL,
  seo_description varchar(300) NOT NULL,seo_keywords jsonb NOT NULL,
  fb_post_url varchar(500) NOT NULL,utm_campaign varchar(120) NOT NULL,
  view_count integer NOT NULL,read_time_minutes smallint NOT NULL,
  published_at timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,
  category_id bigint,trend_id bigint
);
